#include <bits/stdc++.h>
using namespace std;

class Solution {
    double cost(const vector<vector<int>>& p, double x, double y) {
        double ans = 0;
        for (const auto& q : p) ans += hypot(x - q[0], y - q[1]);
        return ans;
    }
public:
    double getMinDistSum(vector<vector<int>>& positions) {
        double x = 0, y = 0;
        for (const auto& p : positions) { x += p[0]; y += p[1]; }
        x /= positions.size(); y /= positions.size();
        // Convex objective: shrinking local search converges to the global minimum.
        double step = 100.0;
        const int dx[4] = {1, -1, 0, 0};
        const int dy[4] = {0, 0, 1, -1};
        double best = cost(positions, x, y);
        while (step > 1e-7) {
            bool improved = false;
            for (int d = 0; d < 4; ++d) {
                double nx = x + step * dx[d], ny = y + step * dy[d];
                double value = cost(positions, nx, ny);
                if (value < best) {
                    x = nx; y = ny; best = value;
                    improved = true;
                    break;
                }
            }
            if (!improved) step *= 0.5;
        }
        return best;
    }
};
